template<typename T>
struct Node {
private:
    T value;
    // Friend declaration for a non-member function template
    template<typename U>
    friend void swap(Node<U>& a, Node<U>& b);
};

template<typename T>
void swap(Node<T>& a, Node<T>& b) {
    // Name lookup (ADL) finds this definition.
    // Access Control allows modification of private members.
    T temp = a.value;
    a.value = b.value;
    b.value = temp;
}
